import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第100章 谁也没开口","description":"","frontmatter":{},"headers":[],"relativePath":"第100章_十二米.md","filePath":"第100章_十二米.md"}'),_={name:"第100章_十二米.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第100章-谁也没开口" tabindex="-1">第100章 谁也没开口 <a class="header-anchor" href="#第100章-谁也没开口" aria-label="Permalink to &quot;第100章 谁也没开口&quot;">​</a></h1><p>她那个进修班，最后落在澄江。</p><p>这件事她自己也没有想到。</p><p>她说，我报了三个地方。</p><p>我说，哪三个。</p><p>她说，一个在这儿，一个在宁城，一个在更南边。</p><p>她说，我以为我会去宁城。</p><p>我说，我也以为我会去宁城。</p><p>她说，那我们现在在同一个城市。</p><p>我说，对。</p><p>她说，你知不知道我今天看到这个通知的时候，我在做什么。</p><p>我说，做什么。</p><p>她说，我在洗一个碗。</p><p>她说，我拿着那个碗，站在那个水池前面，水一直开着。</p><p>她说，我没有高兴。</p><p>她说，我第一反应是：完了。</p><p>我说，为什么是完了。</p><p>她说，因为在这边，我见到你，就变成一件可能的事。</p><p>她说，可能的事我一辈子处理不好。</p><p>她说，以前你在三百公里以外，我在三千里以外，那些都不用我管。</p><p>她说，现在你在一个公交一个半小时的地方。</p><p>她说，我要是有一天忽然特别想见你，我就得决定我去不去。</p><p>她说，我要是去了，我明天就要负责。</p><p>我说，那你可以不去。</p><p>她说，我可以不去。</p><p>她说，可是我今天知道我可以去。</p><p>她说，知道&quot;可以去&quot;这件事，本身就够我难受一整年。</p><p>一月她到了澄江。</p><p>她住城东，一个六个人合租的老楼。</p><p>我住城西，学校后面的那栋。</p><p>我算过那个公交。</p><p>一个半小时。</p><p>中间要换一次，换的那个站在一个菜市场门口。</p><p>她把那个路线截图给我，她说这是她以后每周回家的路。</p><p>她说，我算了一下，我从你学校门口下车，离我那个站还有四站。</p><p>我说，我知道那四站。</p><p>她说，你没坐过。</p><p>我说，我坐过。</p><p>她说，你什么时候。</p><p>我说，我去年十一月从这个城市去那边看我姨，我在那个车上坐了全程。</p><p>她说，你去看你姨，你要坐我那条线？</p><p>我说，那个车经过火车站。</p><p>她说，你什么时候变得这么会找借口。</p><p>我说，我不是找借口。</p><p>我说，我只是那一天在车上把那个菜市场门口那个站，数了一遍。</p><p>她那天没回。</p><p>第二天她上线，第一句是：</p><p>她说，你数了一遍。</p><p>我说，我数了。</p><p>她说，你数到多少。</p><p>我说，十七。</p><p>她说，那我这条线上你数过十七个站。</p><p>她说，你以后每天坐这个车的人会数自己家那一站。</p><p>她说，你数到十七，说明你那天是把我这条线整个看完了。</p><p>我说，我看了。</p><p>她说，你别讲&quot;我看了&quot;。</p><p>她说，你讲这三个字，我要用一整天才能把它放回去。</p><p>二月有一件事，我到现在也不知道我做得对不对。</p><p>那天下午四点，我在一个商场里。</p><p>那个商场是我们这边最大那个，我在里面等一个人，我们约了五点在二楼。</p><p>我在三楼那一层站着，因为我那天要买一个东西。</p><p>我从那个玻璃栏杆看下去。</p><p>一楼那个奶茶店门口，站着一个人。</p><p>那个人穿一件深色的外套，头发扎起来，她低头在看手机。</p><p>她身边有一个女的，比她高一点，两个人在笑。</p><p>我从那个位置看下去，我大概看了六秒钟。</p><p>我认出来了。</p><p>不是因为那件外套。</p><p>是因为她看手机的姿势。</p><p>她拿手机是双手，左手托底，右手大拇指一直在动，她的手肘会往外支。</p><p>这个姿势我看了六年。</p><p>我站在那里。</p><p>我心里第一个念头是很土的：我下去。</p><p>第二个念头是：她身边有人。</p><p>第三个念头是：我要是下去了，她今天这一天就要在她那个朋友面前解释我是谁。</p><p>第四个念头是：她解释不了。</p><p>第五个念头是：她这一辈子解释不了的东西，全部是因为我。</p><p>我那天往旁边走了两步。</p><p>旁边那一家店是一个卖鞋的，门口有一根柱子。</p><p>我站在那根柱子后面。</p><p>我在柱子后面站了十一分钟。</p><p>那十一分钟里我看见她买了那杯东西，看见她跟那个女的上了楼。</p><p>她们从我这一层过去的。</p><p>她们从我面前走过去，大概十二米。</p><p>我没有出去。</p><p>她走过去的时候眼睛在看手机。</p><p>她也可能看了。</p><p>我不知道。</p><p>五点我在二楼见了那个人，那是一个学长，我们讲了一个钟头的事。</p><p>我那天回来的路上，在公交车上，手机在兜里震了一下。</p><p>她说，我今天在商场里看见你了。</p><p>我看着这一句。</p><p>我说，你什么时候。</p><p>她说，三点五十左右，我在楼下，我上楼的时候我在电梯里回头看了一眼。</p><p>她说，我看见你站在一个柱子后面。</p><p>我说，我在等一个店开门。</p><p>她说，那个店是开着的。</p><p>我说，我在打电话。</p><p>她说，你手里没有手机。</p><p>她说，你那时候手里拿着一张传单。</p><p>我说，我捡的。</p><p>她不说话了。</p><p>过了很久，她发了一句。</p><p>她说，你为什么不过来。</p><p>我坐在那个公交车上，看着这七个字。</p><p>我打了三行。</p><p>第一行：因为你身边有人。</p><p>第二行：因为我要是过来，你今天就要跟你那个朋友讲我是谁。</p><p>第三行：因为我算了一下，你那天要是看见我，你上楼以后要开始想我，你那天晚上就画不了。</p><p>我把这三行全删了。</p><p>我打的是：因为我没看见你。</p><p>她回：你看见我了。</p><p>她说：我看见你看见我了。</p><p>她说：你在那个柱子后面站着的时候，你抬了一次头。</p><p>她说：你抬那一次头，我们两个都看见了。</p><p>她说：然后你把头低下去了。</p><p>她说：你低头那一下，我在那儿站了十一分钟没走。</p><p>我说，那你为什么不上来。</p><p>她说，因为我上来了，你要开始装。</p><p>她说，你最会装的那个时候就是有人主动找你。</p><p>她说，我不想到时候我在你脸上看见&quot;你怎么来了&quot;。</p><p>她说，我宁愿你在柱子后面站着。</p><p>那天晚上我们两个一句话也没讲。</p><p>我下线以前发了一句晚安。</p><p>她回了一句晚安。</p><p>我们两个那晚都没有多打一个字。</p><p>那十一分钟，是我这一生里离她最近的一次。</p><p>我们中间隔着一个商场，一层楼，十二米，和一个&quot;她身边有人&quot;。</p><p>我们没有说话。</p><p>我们后来也没有讲这件事。</p><p>那年二月末，她在旧号上发了一条。</p><p>一张很糊的街景，是一个十字口，路边有一个绿色的邮筒。</p><p>那个口是城东那个，就在她那个合租楼下面一百米。</p><p>配的文字是三个字：</p><p>&quot;我到了。&quot;</p><p>底下有十一个赞。</p><p>她妈评论了一个&quot;吃了吗&quot;。</p><p>我坐在城西我这个屋里，看着那三个字。</p><p>我一个也没点。</p><p>我那天夜里在本子上写了一行。</p><p>我写：这一年我们从三百公里，走到了十二米。</p><p>我写：我们没有说话。</p>',142)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
